def test_get_project_workflow_runs_parameter_errors(api_client, merged_test_data, get_config):
    """
    Negative and boundary tests for query parameters:
      - both all-branches and branch provided (mutually exclusive)
      - end-date provided without start-date
    Valid auth is required to focus on parameter error handling.
    """
    token = _valid_token_or_skip(get_config)

    data = merged_test_data(str(_endpoint_data_path))
    cases = _extract_cases(data)
    base_case = cases[0] if cases else {}
    project_slug, workflow_name = _required_path_params_for_case(base_case, get_config)
    endpoint = _build_endpoint(project_slug, workflow_name)
    headers = {"Circle-Token": token}

    # Mutually exclusive parameters provided together
    params_conflict = {
        "all-branches": "true",
        "branch": "main",
    }
    resp_conflict = api_client.get(endpoint, headers=headers, params=params_conflict)
    _assert_default_error_and_validate(resp_conflict, "Conflicting params (all-branches + branch): ")

    # end-date provided without start-date
    params_end_only = {
        "end-date": "2025-01-15T00:00:00Z",
    }
    resp_end_only = api_client.get(endpoint, headers=headers, params=params_end_only)
    _assert_default_error_and_validate(resp_end_only, "end-date without start-date: ")
